import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Login from './Login'; // Ensure this file exists as Login.js or Login.jsx
import Dashboard from './Dashboard'; // Ensure this file exists as Dashboard.js
import FormulaForm from './FormulaForm'; // Our new formula logger!

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          {/* Main App Routes */}
          <Route path="/" element={<Login />} />
          <Route path="/dashboard" element={<Dashboard />} />

          {/* Temporary Route to view and test your new formula form immediately */}
          <Route 
            path="/test-formula" 
            element={<FormulaForm appointmentId={1} token="dummy_token_for_now" />} 
          />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
